22	export const HARNESS = "claude-code";
23	export const RULES_NAME = "CLAUDE.md";
24	export const DEFAULT_ALLOWED_TOOLS = ["Edit", "Write", "Read", "Glob", "Grep", "Bash(bun test:*)", "Bash(bun test)"];
25	/** Tools that exist at all; anything else (Web*, Agent, MCP) is absent, not just denied. */
26	const TOOLS = "Bash,Edit,Write,Read,Glob,Grep";
