28	// Host-session plumbing that would wire the child into the parent session.
29	const SCRUB =
30	  /^(CLAUDECODE|CLAUDE_PID|CLAUDE_CODE_(SESSION_ID|HOST_SESSION_ID|CHILD_SESSION|SESSION_ATTENDED|MESSAGING_.*|ENTRYPOINT|EMIT_TOOL_USE_SUMMARIES|REPORT_FINDINGS|TERMINAL_MCP_TOOLS|ENABLE_ASK_USER_QUESTION_TOOL|SDK_HAS_HOST_AUTH_REFRESH|ENABLE_SDK_FILE_CHECKPOINTING|DESKTOP_APP_VERSION)|CLAUDE_AGENT_SDK_.*|CLAUDE_EFFORT)$/;
