32	export function childEnv(extra: Record<string, string | undefined> = {}): Record<string, string> {
33	  const merged = { ...process.env, ...extra };
34	  return Object.fromEntries(
35	    Object.entries(merged).filter((e): e is [string, string] => e[1] !== undefined && !SCRUB.test(e[0])),
