57	// ---------- git ----------
58	function git(cwd: string, args: string[]): { code: number | null; out: string; err: string } {
59	  const r = Bun.spawnSync(["git", "-c", "core.hooksPath=/dev/null", "-c", "commit.gpgsign=false", ...args], {
60	    cwd,
61	    env: gitEnv(),
62	  });
63	  return { code: r.exitCode, out: r.stdout.toString(), err: r.stderr.toString() };
