81	/** Stages everything the agent did and writes `git diff --binary` against the setup commit. */
82	export function captureDiff(sandboxPath: string, setupSha: string, outDir: string): HarnessDiff {
83	  gitOk(sandboxPath, ["add", "-A"]);
84	  const patchPath = join(outDir, "agent.patch");
85	  writeFileSync(patchPath, gitOk(sandboxPath, ["diff", "--cached", "--binary", setupSha]));
86	  const rows = gitOk(sandboxPath, ["diff", "--cached", "--numstat", setupSha])
87	    .split("\n")
88	    .filter(Boolean)
89	    .map((l) => l.split("\t"));
90	  return {
91	    patchPath,
92	    filesChanged: rows.length,
93	    added: rows.reduce((s, r) => s + (Number(r[0]) || 0), 0),
94	    removed: rows.reduce((s, r) => s + (Number(r[1]) || 0), 0),
95	    files: rows.map((r) => r[2] ?? ""),
96	  };
97	}
