105	// ---------- process ----------
106	interface Exec {
107	  code: number | null;
108	  out: string;
109	  err: string;
110	  timedOut: boolean;
111	  wallMs: number;
112	  spawnError: string | null;
113	}
114	
115	/** Runs in its own process group so a timeout kills the agent's tool subprocesses too. */
116	function exec(bin: string, args: string[], cwd: string, env: Record<string, string>, timeoutMs: number): Promise<Exec> {
117	  const t0 = performance.now();
118	  return new Promise((done) => {
119	    const out: Buffer[] = [];
120	    const err: Buffer[] = [];
121	    let timedOut = false;
122	    let spawnError: string | null = null;
123	    const p = spawn(bin, args, { cwd, env, detached: true, stdio: ["ignore", "pipe", "pipe"] });
124	    const kill = () => {
125	      try {
126	        if (p.pid) process.kill(-p.pid, "SIGKILL");
127	      } catch {
128	        p.kill("SIGKILL");
129	      }
130	    };
131	    const timer = setTimeout(() => {
132	      timedOut = true;
133	      kill();
134	    }, timeoutMs);
135	    p.stdout?.on("data", (b: Buffer) => out.push(b));
136	    p.stderr?.on("data", (b: Buffer) => err.push(b));
137	    p.on("error", (e) => {
138	      spawnError = String(e);
139	    });
140	    p.on("close", (code) => {
141	      clearTimeout(timer);
142	      if (timedOut) kill(); // stragglers that kept the pipes open
143	      done({
144	        code,
145	        out: Buffer.concat(out).toString(),
146	        err: Buffer.concat(err).toString(),
147	        timedOut,
148	        wallMs: Math.round(performance.now() - t0),
149	        spawnError,
150	      });
151	    });
152	  });
153	}
154	
155	// ---------- parsing ----------
156	type Json = Record<string, any>;
157	
158	export function parseResult(stdout: string): Json | null {
159	  const lines = stdout.trim().split("\n").filter(Boolean);
160	  for (let i = lines.length - 1; i >= 0; i--) {
161	    try {
162	      const j = JSON.parse(lines[i] ?? "");
163	      if (j && typeof j === "object" && !Array.isArray(j)) return j;
164	    } catch {}
165	  }
166	  try {
167	    const j = JSON.parse(stdout);
168	    return j && typeof j === "object" && !Array.isArray(j) ? j : null;
169	  } catch {
170	    return null;
171	  }
172	}
173	
174	/** HTTP status of an API failure, from the result text or stderr ("API Error: 529 ..."). */
175	export function apiStatusOf(j: Json | null, stderr: string): number | null {
176	  if (typeof j?.api_error_status === "number") return j.api_error_status;
177	  const text = `${typeof j?.result === "string" ? j.result : ""}\n${stderr}`;
178	  const m = text.match(/API Error:?\s*(\d{3})\b/i) ?? text.match(/\b(429|5\d\d)\b[^\n]*(rate.?limit|overloaded|server|unavailable|timeout)/i);
179	  return m ? Number(m[1]) : null;
180	}
181	
182	const retryable = (s: number | null) => s !== null && (s === 429 || (s >= 500 && s <= 599));
183	
184	function errorKindOf(j: Json | null, x: Exec, apiStatus: number | null): HarnessErrorKind | null {
185	  if (x.timedOut) return "timeout";
186	  if (x.spawnError) return "spawn_failed";
187	  if (!j) return "unparseable_output";
188	  const subtype = String(j.subtype ?? "");
189	  // Auth failures come back as subtype "success" with is_error true: trust is_error, not subtype.
190	  if (!j.is_error && subtype === "success") return null;
191	  if (subtype === "error_max_turns") return "max_turns";
192	  if (/budget/i.test(subtype)) return "budget";
193	  if (apiStatus === 429) return "rate_limited";
194	  if (retryable(apiStatus)) return "server_error";
195	  return "agent_error";
196	}
197	
198	/** The model that did the work: the costliest `modelUsage` entry (background calls use cheaper ones). */
199	export function resolvedModel(j: Json | null): { model: string | null; models: string[] } {
200	  const mu: Json = j?.modelUsage ?? {};
201	  const models = Object.keys(mu);
202	  const weight = (k: string) => Number(mu[k]?.costUSD ?? 0) * 1e9 + Number(mu[k]?.outputTokens ?? 0);
203	  const model = models.length ? models.reduce((a, b) => (weight(b) > weight(a) ? b : a)) : null;
204	  return { model, models };
205	}
206	
207	export function tokensOf(j: Json | null): HarnessTokens {
208	  const mu: Json | undefined = j?.modelUsage;
209	  if (mu && Object.keys(mu).length) {
210	    const sum = (k: string) => Object.values(mu).reduce((s: number, v: any) => s + (Number(v?.[k]) || 0), 0);
211	    return {
212	      input: sum("inputTokens"),
213	      output: sum("outputTokens"),
214	      cacheRead: sum("cacheReadInputTokens"),
215	      cacheWrite: sum("cacheCreationInputTokens"),
216	    };
217	  }
218	  const u: Json = j?.usage ?? {};
219	  return {
220	    input: Number(u.input_tokens) || 0,
221	    output: Number(u.output_tokens) || 0,
222	    cacheRead: Number(u.cache_read_input_tokens) || 0,
223	    cacheWrite: Number(u.cache_creation_input_tokens) || 0,
224	  };
225	}
226	
227	const num = (v: unknown): number | null => (typeof v === "number" && Number.isFinite(v) ? v : null);
228	const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
229	
230	// ---------- entry ----------
231	export async function runClaude(o: HarnessRunOptions): Promise<HarnessResult> {
232	  const sandboxPath = resolve(o.sandboxPath);
233	  const outDir = resolve(o.outDir ?? `${sandboxPath}.out`);
234	  const args = claudeArgs(o);
235	  const bin = o.bin ?? "claude";
236	  const res: HarnessResult = {
237	    harness: HARNESS, sessionId: null, model: null, models: [], turns: null, durationMs: null, costUsd: null,
238	    tokens: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 }, isError: true, errorKind: null, stopReason: null,
239	    transcriptPath: null, diff: null, setupSha: null, attempts: [], command: [bin, ...args],
240	  };
241	
242	  try {
243	    mkdirSync(outDir, { recursive: true });
244	    res.setupSha = swapRules(sandboxPath, o.rulesFile);
245	  } catch (e) {
246	    res.errorKind = "setup_failed";
247	    writeFileSync(join(outDir, "error.txt"), String(e));
248	    return res;
249	  }
250	
251	  const env = childEnv(o.env);
252	  const maxRetries = o.maxRetries ?? 2;
253	  let last: Json | null = null;
254	  const setupSha = res.setupSha;
255	  for (let n = 1; ; n++) {
256	    if (n > 1) {
257	      try {
258	        resetTo(sandboxPath, setupSha);
259	      } catch (e) {
260	        writeFileSync(join(outDir, "error.txt"), String(e));
261	        break; // keep the last attempt's verdict rather than run on a dirty sandbox
262	      }
263	    }
264	    const x = await exec(bin, args, sandboxPath, env, o.timeoutMs);
265	    const j = parseResult(x.out);
266	    const apiStatus = x.timedOut ? null : apiStatusOf(j, x.err);
267	    const errorKind = errorKindOf(j, x, apiStatus);
268	    const rawPath = join(outDir, `claude.attempt-${n}.json`);
269	    writeFileSync(rawPath, j ? JSON.stringify(j, null, 2) : JSON.stringify({ stdout: x.out, stderr: x.err.slice(-4000), spawnError: x.spawnError }, null, 2));
270	    const costUsd = num(j?.total_cost_usd);
271	    res.attempts.push({ n, exitCode: x.code, timedOut: x.timedOut, wallMs: x.wallMs, isError: errorKind !== null, errorKind, apiStatus, rawPath, costUsd });
272	    if (costUsd !== null) res.costUsd = (res.costUsd ?? 0) + costUsd;
273	    const t = tokensOf(j);
274	    res.tokens = { input: res.tokens.input + t.input, output: res.tokens.output + t.output, cacheRead: res.tokens.cacheRead + t.cacheRead, cacheWrite: res.tokens.cacheWrite + t.cacheWrite };
275	    last = j;
276	    res.isError = errorKind !== null;
277	    res.errorKind = errorKind;
278	    res.transcriptPath = rawPath;
279	    if (!(errorKind !== null && retryable(apiStatus) && n <= maxRetries)) break;
280	    await sleep((o.retryBaseMs ?? 2000) * 2 ** (n - 1));
281	  }
282	
283	  const { model, models } = resolvedModel(last);
284	  res.model = model;
285	  res.models = models;
286	  res.sessionId = typeof last?.session_id === "string" ? last.session_id : null;
287	  res.turns = num(last?.num_turns);
288	  res.durationMs = num(last?.duration_ms) ?? res.attempts.at(-1)?.wallMs ?? null;
289	  res.stopReason = last?.terminal_reason ?? last?.stop_reason ?? null;
290	  writeFileSync(join(outDir, "claude.json"), readFileSync(res.transcriptPath!, "utf8"));
291	  res.transcriptPath = join(outDir, "claude.json");
292	
293	  // Partial work is still evidence: capture the diff even when the agent errored.
294	  try {
295	    res.diff = captureDiff(sandboxPath, res.setupSha, outDir);
296	  } catch (e) {
297	    writeFileSync(join(outDir, "error.txt"), String(e));
298	    if (!res.isError) {
299	      res.isError = true;
300	      res.errorKind = "setup_failed";
301	    }
302	  }
303	  return res;
304	}
